(function(){var e=document.documentElement;document.querySelectorAll(".theme-toggle").forEach(function(t){t.addEventListener("click",function(){var t=e.getAttribute("data-theme")==="dark"?"light":"dark";e.setAttribute("data-theme",t);try{localStorage.setItem("theme",t)}catch{}})}),document.querySelectorAll(".print-button").forEach(function(e){e.hidden=!1,e.addEventListener("click",function(){window.print()})})})()